1: // SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1
2: // Passive transport accounting for the optional PN configuration guard.
3: // These are transaction debts, not advertised credits. No output gates AXI.
4: module rv_iommu_ds_debt (
5:     input  logic clk_i,
6:     input  logic rst_ni,
7:     input  logic read_issue_i,
8:     input  logic read_last_i,
9:     input  logic write_issue_i,
10:     input  logic write_done_i,
11:     output logic quiet_o
12: );
13:     logic [7:0] read_q, read_n, write_q, write_n;
14:     logic bad_q, bad_n;
15: 
16:     always_comb begin
17:         read_n = read_q;
18:         write_n = write_q;
19:         bad_n = bad_q;
20:         // Simultaneous issue/retirement is a net zero, including at 0/255.
21:         unique case ({read_issue_i, read_last_i})
22:             2'b10: if (&read_q) bad_n = 1'b1;
23:                    else read_n = read_q + 8'd1;
24:             2'b01: if (read_q == '0) bad_n = 1'b1;
25:                    else read_n = read_q - 8'd1;
26:             default: ;
27:         endcase
28:         unique case ({write_issue_i, write_done_i})
29:             2'b10: if (&write_q) bad_n = 1'b1;
30:                    else write_n = write_q + 8'd1;
31:             2'b01: if (write_q == '0) bad_n = 1'b1;
32:                    else write_n = write_q - 8'd1;
33:             default: ;
34:         endcase
35:     end
36: 
37:     always_ff @(posedge clk_i or negedge rst_ni) begin
38:         if (!rst_ni) begin
39:             read_q <= '0;
40:             write_q <= '0;
41:             bad_q <= 1'b0;
42:         end else begin
43:             read_q <= read_n;
44:             write_q <= write_n;
45:             bad_q <= bad_n;
46:         end
47:     end
48:     // A range/protocol anomaly cannot be cleared by ARM, STOP or policy clear.
49:     assign quiet_o = !bad_q && (read_q == '0) && (write_q == '0);
50: endmodule
